(()=>{
let installPrompt=null,ready=false;const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;document.body.classList.toggle('is-standalone',!!standalone);
const dialog=document.createElement('dialog');dialog.id='install-dialog';dialog.innerHTML='<div class="modal-content"><span class="eyebrow">独立窗口 · 主屏幕启动</span><h2>把王国装进手机</h2><p>这是可安装的网页 App（PWA），不是 App Store 原生安装包。</p><ol><li>在 iPhone 的 <b>Safari</b> 中打开此游戏。</li><li>点“分享”，选择 <b>添加到主屏幕</b>。</li><li>开启 <b>作为网页 App 打开</b>（Open as Web App），然后点“添加”。</li></ol><p>Android / 电脑可使用浏览器的“安装应用”功能。安装后从图标启动，游戏独立全屏显示。</p><p id="offline-detail">正在检查离线资源…</p><button id="native-install" class="primary" hidden>安装应用</button><button id="close-install" class="secondary">返回游戏</button><a href="https://webkit.org/blog/17333/webkit-features-in-safari-26-0/#every-site-can-be-a-web-app-on-ios-and-ipados" target="_blank" rel="noopener">Apple WebKit 安装说明</a></div>';document.body.append(dialog);
function status(text){const e=document.getElementById('offline-status');if(e)e.textContent=text;document.getElementById('offline-detail').textContent=text}
function offlineReady(){ready=true;status('离线资源已就绪；当前战局保存在本机。')}
for(const b of document.querySelectorAll('.install-app'))b.onclick=()=>{document.getElementById('native-install').hidden=!installPrompt;status(ready?'离线资源已就绪；首次联网加载后可离线游玩。':'离线资源正在缓存，请保持联网至提示就绪。');dialog.showModal()};document.getElementById('close-install').onclick=()=>dialog.close();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.getElementById('native-install').hidden=false});document.getElementById('native-install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;document.getElementById('native-install').hidden=true};window.addEventListener('appinstalled',()=>{document.body.classList.add('is-standalone');status('已安装到设备，可从应用图标启动。')});
if('serviceWorker'in navigator){status('正在缓存离线资源，首次加载请保持联网…');navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_READY')offlineReady()});navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(reg=>{if(reg.active)reg.active.postMessage({type:'STATUS'});const watch=worker=>{if(worker)worker.addEventListener('statechange',()=>{if(worker.state==='activated')offlineReady()})};watch(reg.installing);reg.addEventListener('updatefound',()=>watch(reg.installing));return navigator.serviceWorker.ready}).then(reg=>reg.active?.postMessage({type:'STATUS'})).catch(()=>status('当前浏览器未启用离线缓存；仍可联网游玩。'))}else status('当前浏览器不支持离线缓存，请联网游玩。');
})();
